CREATE TABLE "public"."projects" (
  "id"          bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "title"       text   NOT NULL,
  "description" text,
  CONSTRAINT "projects_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."projects"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Authenticated users can insert about" ON "public"."about"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((auth.uid() IS NOT NULL));

CREATE POLICY "Authenticated users can update about" ON "public"."about"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() IS NOT NULL))
  WITH CHECK ((auth.uid() IS NOT NULL));

CREATE POLICY "Authenticated users can update skills" ON "public"."skills"
  FOR UPDATE
  TO "authenticated"
  USING ((auth.uid() IS NOT NULL))
  WITH CHECK ((auth.uid() IS NOT NULL));

REVOKE ALL ON SEQUENCE "public"."projects_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."projects_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."projects_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."projects_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."projects_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."projects_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."projects_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."projects_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."projects" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."projects" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."projects" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."projects" TO "service_role";

